INSERT INTO `products` VALUES (1,1,1,'iPhone 15 Pro Max 256GB Titan Tự Nhiên','iphone-15-pro-max-256gb','APL-IP15PM-256',29990000.00,26000000.00,'iPhone 15 Pro Max khung viền titan siêu nhẹ, chip A17 Pro đỉnh cao, camera tiềm vọng zoom quang 5x ấn tượng.','{\"Màn hình\": \"6.7 inch Super Retina XDR\", \"Chip\": \"Apple A17 Pro 3nm\", \"RAM\": \"8GB\", \"Bộ nhớ\": \"256GB\", \"Pin\": \"4422 mAh\"}','ACTIVE','2026-09-21 22:21:28','2026-09-22 16:05:28',NULL),(2,2,1,'MacBook Pro 14 M3 Pro 18GB/512GB Space Black','macbook-pro-14-m3-pro','APL-MBP14-M3P',49990000.00,44000000.00,'MacBook Pro 14 inch trang bị chip M3 Pro mạnh mẽ, màn hình Liquid Retina XDR 120Hz sắc nét đỉnh cao.','{\"Màn hình\": \"14.2 inch Liquid Retina XDR\", \"CPU\": \"Apple M3 Pro 11 Core\", \"GPU\": \"14 Core\", \"RAM\": \"18GB\", \"Ổ cứng\": \"512GB SSD\"}','ACTIVE','2026-09-21 22:21:28','2026-09-22 16:05:28',NULL),(3,1,2,'Samsung Galaxy S24 Ultra 12GB/256GB Titan Xám','samsung-galaxy-s24-ultra','SS-S24U-256',25290000.00,24000000.00,'Galaxy S24 Ultra tích hợp Galaxy AI thông minh vượt trội, bút S-Pen tiện lợi, chip Snapdragon 8 Gen 3 for Galaxy.','{\"Kích thước màn hình\": \"6.8 inches\", \"Công nghệ màn hình\": \"Dynamic AMOLED 2X\", \"Camera sau\": \"Camera chính: 200MP, Laser AF, OIS Camera: 50MP,  PDAF, OIS, zoom quang học 5xCamera tele: 10MPCamera góc siêu rộng: 12 MP, f/2.2, 13mm, 120˚\", \"Camera trước\": \"12 MP, f/2.2\", \"Chipset\": \"Snapdragon 8 Gen 3 For Galaxy\", \"Công nghệ NFC\": \"Có\", \"Dung lượng RAM\": \"12 GB\", \"Bộ nhớ trong\": \"256 GB\", \"Pin\": \"5,000mAh \", \"Thẻ SIM\": \"SIM 1 + SIM 2 / SIM 1 + eSIM / 2 eSIM\", \"Hệ điều hành\": \"Android 14, One UI 6.1\", \"Độ phân giải màn hình\": \"1440 x 3120 pixels\", \"Tính năng màn hình\": \"Độ sáng cao nhất 2,600 nits, 120Hz, Corning® Gorilla® Armor®, 16 triệu màu\", \"Loại CPU\": \"3.39GHz,3.1GHz,2.9GHz,2.2GHz\", \"Tương thích\": \"Bút SPEN - tích hợp sẵn lên máy\"}','ACTIVE','2026-09-21 22:21:28','2026-10-03 14:22:28',NULL),(4,